def _sha256(path: str, chunk: int = 65536) -> Optional[str]:
    """Compute SHA256 of a file. Returns None on any read error."""
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            while True:
                buf = f.read(chunk)
                if not buf:
                    break
                h.update(buf)
        return h.hexdigest()
    except Exception:
        return None

